CREATE TRIGGER payments_match_batch BEFORE INSERT ON payments
WHEN NEW.batch_id IS NOT NULL AND (
  NOT EXISTS (
    SELECT 1 FROM payment_batches b JOIN charges c ON c.client_id = b.client_id
    WHERE b.id = NEW.batch_id AND c.id = NEW.charge_id AND b.paid_at = NEW.paid_at
      AND (b.voided_at IS NULL OR NEW.voided_at IS NOT NULL)
      AND NEW.amount_minor <= b.total_minor - (
        SELECT COALESCE(SUM(amount_minor), 0) FROM payments WHERE batch_id = b.id
      )
  ) OR (SELECT COUNT(*) FROM payments WHERE batch_id = NEW.batch_id) >= 12
)
BEGIN
  SELECT RAISE(ABORT, 'El pago no corresponde al grupo.');
END;

CREATE TRIGGER payments_exact_amount BEFORE INSERT ON payments
WHEN NEW.voided_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM charges WHERE id = NEW.charge_id AND amount_minor = NEW.amount_minor)
BEGIN
  SELECT RAISE(ABORT, 'El importe debe coincidir con un cargo existente.');
END;

CREATE TRIGGER payment_batches_void_children AFTER UPDATE OF voided_at ON payment_batches
BEGIN
  UPDATE payments SET voided_at = NEW.voided_at WHERE batch_id = NEW.id AND voided_at IS NULL;
END;
